function sameDepthDifferentParents(root: TreeNode | null, x: number, y: number): boolean {
  const info = new Map<number, [number, number]>(); // value -> [depth, parent]
  const walk = (n: TreeNode | null, depth: number, parent: number): void => {
    if (!n) return;
    if (n.val === x || n.val === y) info.set(n.val, [depth, parent]);
    walk(n.left, depth + 1, n.val);
    walk(n.right, depth + 1, n.val);
  };
  walk(root, 0, -1);
  const [dx, px] = info.get(x)!, [dy, py] = info.get(y)!;
  return dx === dy && px !== py;
}

