function sameDepthDifferentParents(root: TreeNode | null, x: number, y: number): boolean {
  let level: TreeNode[] = root ? [root] : [];
  while (level.length) {
    let seenX = false, seenY = false;
    const next: TreeNode[] = [];
    for (const n of level) {
      if (n.val === x) seenX = true;
      if (n.val === y) seenY = true;
      if (n.left && n.right) {
        const a = n.left.val, b = n.right.val;
        if ((a === x && b === y) || (a === y && b === x)) return false; // siblings
      }
      if (n.left) next.push(n.left);
      if (n.right) next.push(n.right);
    }
    if (seenX && seenY) return true;
    if (seenX || seenY) return false;
    level = next;
  }
  return false;
}

